"""Render the Markdown research report and source-volume sensitivities offline."""
import csv,json,re
from acquire import H
from build_turnout import rank,dump

def main():
    rows=list(csv.DictReader((H/'../county-turnout.csv').open()));c=json.loads((H/'controls.json').read_text());u=json.loads((H/'candidate-universe.json').read_text());p=json.loads((H/'priority-set.json').read_text());legacy=json.loads((H/'legacy-reconciliation.json').read_text());native=json.loads((H/'legacy-json-reconciliation.json').read_text())
    sensitivities=[]
    for year in [2024,2022,2020]:
        for basis in ['registered','ballots']:
            field=f'enr_{year}_election_{basis}_control';r=[dict(geography_key=x['geography_key'],name=x['county'],value=int(x[field]))for x in rows];order,stat=rank(r,'value');sensitivities.append(dict(year=year,basis='original ENR election '+basis,**stat,order=order))
    dump('legacy-volume-sensitivity.json',sensitivities)
    election_ledger={}
    for year in [2024,2022,2020]:
        parent=legacy['state_election_controls'][str(year)]['election_voter_turnout']
        sums={field:sum(int(r[f'enr_{year}_election_{field}_control'])for r in rows)for field in ['registered','ballots']}
        election_ledger[str(year)]={'source_id':f'legacy{year}-detailxml','state_parent_attributes':parent,'all46_child_county_registered_sum':sums['registered'],'all46_child_county_ballots_sum':sums['ballots'],'registered_child_minus_parent':sums['registered']-int(parent['totalVoters']),'ballots_child_minus_parent':sums['ballots']-int(parent['ballotsCast']),'scope':'source-published fields retained independently; no allocation or cause inferred'}
    dump('legacy-state-election-reconciliation.json',election_ledger)
    text=['# South Carolina: complete historical vote-volume geography\n',
    'Research observed **2026-10-18 UTC**. Fractions and integer counts are exact; decimal percentages are rounded displays. The **2024 presidential** baseline is **2,548,140 reported candidate votes**, supported by all seven slates in the signed state certificate and independently reconciled official state/county originals. The top 15 counties contribute **1,974,167 / 2,548,140 = 77.47482477414898%**. The minimum descending county prefix reaching 80% has **17 counties**, ending at **Oconee**: **2,061,601 / 2,548,140 = 80.90611190907877%**. [Signed SC certificate](https://www.archives.gov/files/electoral-college/2024/ascertainment-south-carolina.pdf), [official original XML ZIP](https://www.enr-scvotes.org/SC/122436/359624/reports/detailxml.zip), [exact contract](data/turnout/priority-set.json).\n',
    'The exact integer threshold is **2,038,512**. The preceding **16 counties have 2,019,337 votes**, 19,175 short; Oconee adds **42,264**. The remaining **29 counties contribute 486,539 votes (19.09388809092123%)**, all retained in state arithmetic. Sort is votes descending, then full geography key ascending for ties; no rounded percentage determines the crossing. The dispatch union of top15 and minimum80 is this same 17-county set.\n',
    'The complete [county table](data/county-turnout.csv) has every candidate, generic write-in and separate control. The [native orders](data/turnout/extracts/2024-pres-native-order.csv) and [original combined-native order](data/turnout/extracts/2024-pres-original-combined-native-order.csv) preserve every finer reporting identity. The contract is a research dispatch artifact; geographic/legal acceptance is controlled only by its state-relative `coordinator_acceptance_path`, with no reverse hash or self-acceptance.\n',
    '## Actual elections and outcome rules\n',
    'South Carolina had **no 2024 Senate general election**; 2024 president is the stated priority. **2020 Graham–Harrison–Bledsoe** is the previous **Class II** election for this seat. **2022 Scott–Matthews** is the other **Class III** seat and the actual recent midterm; the **2022 governor/lieutenant-governor tickets** are separate context. Original event dates are November 5, 2024; November 3, 2020; and November 8, 2022. The regular Class II general election is **November 3, 2026**. [Class II](https://www.senate.gov/senators/Class_II.htm), [Class III](https://www.senate.gov/senators/Class_III.htm), [official calendars](https://scvotes.gov/elections-statistics/general-election-calendars/), [2020 original](https://www.enr-scvotes.org/SC/106502/277849/reports/detailxml.zip), [2022 original](https://www.enr-scvotes.org/SC/115412/313728/reports/detailxml.zip).\n',
    'The November federal contest uses **plurality**. A tie can require a separate tie-breaking election under SC7-13-2210. A primary requires a majority for nomination (7-17-600/610); its ordinary second primary is two weeks later under 7-13-50. These are different rules. The 1%-or-less statutory recount provision is 7-17-280 and is not a majority runoff. Historical or current primary candidates/counts are not November votes. [Official county 2026 federal election rules](https://cherokeecountysc.gov/voter-registration-election-board/2026-election-dates/), [chapter 13](https://www.scstatehouse.gov/code/t07c013.php), [chapter 17](https://www.scstatehouse.gov/code/t07c017.php).\n',
    '## Complete county order\n',
    'All counts below are contest candidate/write-in votes, including minor candidates. The 2024 values reconcile independently to every candidate in the official state original and all 46 county originals; the 2020/2022 columns reconcile to their own separate originals. County FIPS are from the [Census county code original](https://www2.census.gov/geo/docs/reference/codes2020/national_county2020.txt). The compatibility filename is legitimate for these actual county parents; finer units remain separate. [2024 primary](https://www.enr-scvotes.org/SC/122436/359624/reports/detailxml.zip), [2020 primary](https://www.enr-scvotes.org/SC/106502/277849/reports/detailxml.zip), [2022 primary](https://www.enr-scvotes.org/SC/115412/313728/reports/detailxml.zip).\n',
    '| Rank | County | FIPS | 2024 president | Cumulative | Cumulative % | 2020 Senate | 2022 Senate | 2022 governor |\n| ---: | --- | --- | ---: | ---: | ---: | ---: | ---: | ---: |']
    for r in rows:
        text.append(f'| {r["rank_2024_pres"]} | {r["county"]} | {r["county_fips"]} | {int(r["votes_2024_pres"]):,} | {int(r["cumulative_2024_pres"]):,} | {100*int(r["cumulative_2024_pres"])/p["total"]:.6f} | {int(r["2020_senate_candidate_votes"]):,} | {int(r["2022_senate_candidate_votes"]):,} | {int(r["2022_governor_candidate_votes"]):,} |')
    text+=['\n## Candidate universe and primary control disagreements\n',
    'The following are the source-preserved named/ballot identities. Source spellings, candidate IDs, parties, flags and pseudocandidates remain in [complete metadata](data/turnout/candidate-universe.json) and [original choice identities](data/turnout/legacy-candidate-identities.json). The historical database is an official-linked presentation, with its own import/verification metadata, not a replacement for original party labels. [History database authority](https://scvotes.gov/elections-statistics/election-database/), [2024 signed certificate](https://www.archives.gov/files/electoral-college/2024/ascertainment-south-carolina.pdf), [2020/2022 originals](https://scvotes.gov/elections-statistics/election-results/).\n',
    '| Contest | Named candidate/slate or generic scope | DB party | Votes |\n| --- | --- | --- | ---: |']
    for label,universe in u.items():
        parties={int(x['id']):x['name']for x in universe['party_metadata']}
        for ca in universe['candidate_metadata']:
            if ca['candidateId']in universe['real_candidate_ids']:text.append(f'| {label} | {ca["displayName"]} | {parties.get(ca["partyId"],"generic Write-In")} | {ca["nVotes"]:,} |')
    text+=['\nThe signed December 9, 2024 certificate includes **Terry/Broden 5,352**, matching the official original XML and database. The [House Clerk 2024 PDF](https://clerk.house.gov/member_info/electionInfo/2024/statistics2024.pdf), PDF page64/printed62, actually prints six presidential party rows and omits that slate: its listed sum is **2,542,788**, not the complete 2,548,140. Both actual pages were visually checked; no omission cause or release chronology is inferred. Presidential/vice-presidential repeated totals and elector names are not additional votes.\n',
    'The [House Clerk 2020 PDF](https://clerk.house.gov/member_info/electionInfo/2020/statistics2020.pdf), PDF page62/printed60, prints three SC Senate named candidates totaling **2,512,810** and omits the original/database generic **2,294 Write-In**; the full contest is **2,515,104**. It labels Bledsoe **Constitution**, corroborated by original ENR party **CON**. The database instead labels party274 **Conservative**; both identities are retained. The [2022 Clerk PDF](https://clerk.house.gov/member_info/electionInfo/2022/statistics2022.pdf), PDF page44/printed42, includes Scott, Matthews and **1,812 generic Write-In**, matching **1,695,702**. Neither omitted scope is forced to zero.\n',
    'Generic `ALL_OTHER_CANDIDATES` is not an independently identified named or legally valid write-in subset; none is supplied. Presidential write-in space is excluded by **SC7-13-360**, consistent with the seven-slate universe and absence of a generic presidential option. `TOTAL_VOTES`, `TOTAL_BALLOTS` and combined `Overvotes/Undervotes` are overlapping controls, never extra candidates. [SC chapter13](https://www.scstatehouse.gov/code/t07c013.php), [source schema](data/turnout/source/SCHEMA.md).\n',
    '## Native reporting geography and original coverage\n',
    'Every returned hierarchy is preserved: state → all46 counties → **2,446 native 2024 president, 2,399 native 2020 Senate, and 2,395 each 2022 Senate/governor**. Their combined candidate vectors reconcile exactly at every level. There are **138 explicitly named Failsafe/Provisional/Failsafe Provisional administrative contexts per contest**, plus all other names, zero-vote and Central identities. The original reports count participating precincts **2,308 / 2,261 / 2,257**, a different field from identity counts. Do not infer polygons or a crosswalk from those differences. Database native IDs, original JSON row ordinals/labels, and VHM codes are separate source systems. [Official history](https://electionhistory.scvotes.gov/), [original 2024](https://www.enr-scvotes.org/SC/122436/359624/reports/detailxml.zip), [original 2020](https://www.enr-scvotes.org/SC/106502/277849/reports/detailxml.zip), [original 2022](https://www.enr-scvotes.org/SC/115412/313728/reports/detailxml.zip).\n',
    'At the finest 2024 native level, the top15 have **63,074 / 2,548,140 = 2.4752957058874316%**. The first **1,380 have 2,038,464**; **Congaree02, Lexington, DB11109**, adds **819**, crossing at **1,381 units with 2,039,283 votes (80.03025736419507%)**. The native remainder has **508,857 votes**. Full orders include zero units and stable key ties. The [database order](data/turnout/extracts/2024-pres-native-order.csv) and [original combined order](data/turnout/extracts/2024-pres-original-combined-native-order.csv) remain separate. Same-year equal candidate-vector multisets are numerical corroboration, not a geographic join.\n',
    'All138 county original combined JSON/English summary pairs were independently extracted read-only from exact-hash originals. Original method sources cover **137 county XMLs plus Clarendon2022 TXT**, and three state XMLs. Clarendon explicitly disables XML; pinned/current XML404 responses remain, while enabled original TXT/XLS downloads provide the methods. Its pinned registration fields are zero; a later current version has different registration, preserved without substitution. Original method labels include Charleston **Provionsal**; comparison-only aliases and Newberry’s missing Write-In party attribute are documented. [Exact source observations](data/turnout/legacy-observations.json), [combined JSON/TXT observations](data/turnout/legacy-json-observations.json), [full original reconciliation](data/turnout/legacy-json-reconciliation.json), [Clarendon original TXT](https://www.enr-scvotes.org/SC/Clarendon/115426/313514/reports/detailtxt.zip).\n',
    'The historical database has **95 positive candidate-method differences in26 2020 precinct contexts** (Horry7, Lancaster6, Spartanburg13) and **51 method hierarchy residual cells**. Its own state/county method controls still reconcile to the original reports. The complete original finer methods are retained independently, with exact method-parent/native-child balances; this provides a usable historical source scope without allocating the database gaps or asserting their cause. Separate original and database raw rows remain visible in [controls](data/turnout/controls.json), [original XML cells](data/turnout/extracts/legacy-candidate-methods.csv.gz) and [Clarendon TXT cells](data/turnout/extracts/clarendon-2022-txt-candidate-methods.csv).\n',
    '## Ballots, registration and method sensitivity\n',
    'Candidate votes are not ballots cast. Separate blank, undervote and overvote fields are unavailable in these statewide history/XML/JSON scopes; the database publishes combined under/over controls. Original native election-ballot and registration fields are retained where supplied, including omitted/zero administrative cases; a difference between election ballots and candidate votes is not relabeled as a measured undervote count. [Original election controls](data/turnout/extracts/legacy-turnout-controls.csv.gz), [published participation summary](https://scvotes.gov/wp-content/uploads/2026/10/Voter-Participation-History-1998-2026.pdf).\n',
    '| Scope | 2024 | 2022 | 2020 |\n| --- | ---: | ---: | ---: |\n| Original ENR election ballots | 2,566,404 | 1,718,626 | 2,533,010 |\n| Original ENR election totalVoters | 3,343,423 | 3,379,089 | 3,513,225 |\n| BCM summary Total Registered | 3,414,652 | 3,379,089 | 3,513,225 |\n| VHM printed-list registered | 3,851,932 | 3,740,742 | 3,733,793 |\n| VHM participating | 2,553,186 | 1,720,378 | 2,521,038 |\n',
    'The [BCM summary](https://scvotes.gov/wp-content/uploads/2026/10/Voter-Participation-History-1998-2026.pdf) labels Total Registered without specifying historical active/inactive status. The [VHM authority](https://vrems.scvotes.sc.gov/Statistics/VoterHistoryResults) explicitly includes all active and some inactive voters printed on election lists; participants come from list markings/returns, which can differ from tabulation. **2024 original ENR registration differs from the BCM summary by71,229**; definition/cause is unresolved. The **2022 original state registration parent is3,379,089 but its46 county attributes sum3,379,129, a40-registration discrepancy**; election ballots still sum exactly1,718,626. Both registration values remain in the [state/child ledger](data/turnout/legacy-state-election-reconciliation.json), with no allocation or inferred cause. The **2020 Senate database ballot control is2,532,829**, with **17,725 combined under/over**, while the election-wide original/BCM has **2,533,010**, difference181. The separately observed 2020 presidential database control2,532,830 is another contest scope. These values are not rescaled.\n',
    'VHM includes all46 requested counties and **2,343 / 2,270 / 2,465 returned native labels** for2024/2022/2020; every county rollup is exact. Its2024 unnamed administrative county row contributes **2 registrations/1 participant** outside named counties. REG and VOT views overlap; REG’s structural participation zero is retained raw but interpreted as unavailable participation. Returned precinct rows have county=null; the county is the explicit request context. Sparse Greenville rows named Barksdale-Narnie, Keowee and Monarch Box1 remain literally preserved. The authority does not explain whether these labels represent election-day physical membership versus later voter-history/address context; that geographic meaning remains unresolved. **No VHM-to-results or cross-year precinct join is made.** [Actual parent/JS/request provenance](data/turnout/source/voter-history.meta.json), [registration reconciliation](data/turnout/registration-reconciliation.json).\n',
    '| Independently ranked basis | Total | Top15 % | Minimum80 units | Crossing |\n| --- | ---: | ---: | ---: | --- |']
    for label,v in c.items():
        st=v['county_ranking'];text.append(f'| {label} candidate votes | {st["total"]:,} | {st["top15_pct"]:.6f} | {st["minimum80_count"]} | {st["crossing_name"]} |')
    for s in sensitivities:text.append(f'| {s["year"]} {s["basis"]} | {s["total"]:,} | {s["top15_pct"]:.6f} | {s["minimum80_count"]} | {s["crossing_name"]} |')
    for s in json.loads((H/'sensitivity.json').read_text()):
        if s['contest'].startswith('vhm'):text.append(f'| {s["contest"]} {s["basis"]} | {s["total"]:,} | {s["top15_pct"]:.6f} | {s["minimum80_count"]} | {s["crossing_name"]} |')
    text+=['\nAll182 available required county XML native-ballot rollups are exact. Native registration sums disagree with their county VoterTurnout controls in151of182 contexts; both sides remain separate, with no allocation or assumed definition. These are separate observed volume/registration sensitivities, not2026 turnout forecasts. Complete orders, preceding prefixes, crossings and remainders are in [source-volume sensitivity](data/turnout/legacy-volume-sensitivity.json), [other sensitivities](data/turnout/sensitivity.json) and [all-county rankings](data/turnout/extracts/county-rankings.csv). The midterm comparator is the actual2022 electorate, not an invented2024 Senate/governor contest.\n',
    'Raw state candidate-method votes are preserved by source labels. In2024: mail106,800; early1,467,109; Election Day967,968; Failsafe1,782; Provisional2,585; Failsafe Provisional1,896. In2022 Senate: mail69,426; early539,914; Election Day1,080,308; Failsafe2,235; Provisional1,628; Failsafe Provisional2,191. Both the original reports and database match those candidate-channel values. However, the [published absentee/early ballot history](https://scvotes.gov/wp-content/uploads/2026/10/Voter-History-Absentee-History-1998-2026.pdf) lists2022 absentee ballots58,062 and early ballots561,563: the mail candidate total exceeds that separately published ballot statistic. The source-scope discrepancy remains unresolved; method labels are not silently swapped. Its2024 ballot figures108,970 mail/1,471,663 early and2020 absentee1,333,972 are separate controls.\n',
    '## Reproduction, provenance and review\n',
    'Run, in order, `PYTHONDONTWRITEBYTECODE=1 python3 senate/2026/south-carolina/data/turnout/build_turnout.py`, then `extract_legacy.py`, `extract_legacy_json.py`, `write_report.py`, `compare_peer.py`, and `validate_turnout.py --seal` at that same directory path. Default `validate_turnout.py` verifies the sealed package offline. Acquisition is in [acquire.py](data/turnout/acquire.py); exact URLs/requests, redirects/headers, UTC clocks, complete raw originals and stored/original hashes remain in source metadata and [asset manifest](data/turnout/asset-manifest.json). ZIP members and gzip originals reconstruct complete ordered bytes; no file is truncated or simplified, and every stored object is strictly below40,000,000 bytes.\n',
    'The [schema](data/turnout/source/SCHEMA.md), [offline validation](data/turnout/validation.json) and [independent peer comparison](data/turnout/peer-agreement.json) document complete fields, coverage, denominators, source gaps, full orders, minimum integer80 and hash/link checks. Peer work is read-only and independent; coordinator acceptance is separate. Source/native IDs have no implied Georgia/North Carolina equivalence: cross-border newsroom scopes stay intact in the read-only preparation and only verified SC election/contest/geography rows enter these historical totals. No implemented collector, measured November cadence, calibrated Needle, real2026 turnout forecast or approved current precinct geometry is claimed.\n']
    rendered='\n'.join(text).replace('Monarch Box1','`Monarch Box1`')
    for year in ['2024','2020','2022']:rendered=rendered.replace('['+year+' primary]','['+year+' original general results]')
    # Improve prose spacing without altering literal links, code or source labels.
    parts=re.split(r'(`[^`]*`|\[[^\]]+\]\([^)]+\))',rendered)
    for i in range(0,len(parts),2):
        parts[i]=re.sub(r'(?<=[A-Za-z])(?=\d)|(?<=\d)(?=[A-Za-z])',' ',parts[i])
    (H/'../../turnout.md').write_text(''.join(parts))
if __name__=='__main__':main()
